INSERT INTO `branches` (`id`, `institution_id`, `name`, `name_bn`, `code`, `subdomain`, `type`, `email`, `phone`, `address`, `principal_name`, `logo_path`, `cover_path`, `latitude`, `longitude`, `primary_color`, `timezone`, `currency`, `locale`, `status`, `established_on`, `sort_order`, `settings`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, 'BAF Shaheen College Dhaka (Dhaka Cantonment)', 'বিএএফ শাহীন কলেজ ঢাকা (ঢাকা সেনানিবাস)', 'BR01', 'bafd', 'school_college', 'info@bafsd.edu.bd', '+8802-9836440', '3rd Gate, Near Shaheed Jahangir Gate, Dhaka 1206', 'Principal BAF Shaheen College Dhaka', NULL, 'branches/1/EbabqVVPCsvgFKHr4qRCxzxJAenCRJAP4pVC8MEh.jpg', 23.7758583, 90.3913403, '#0d80d5', 'Asia/Dhaka', 'BDT', 'en', 'active', NULL, 1, '{\"website\": {\"hero\": {\"image\": \"website/branch-1/hero/cZqvTz8xCAjANXELpWn8xCl7SprKF6uH8xX6InVB.jpg\", \"features\": [{\"icon\": \"fa-pencil\", \"text\": \"Individual attention, structured teaching and a strong academic foundation for every learner.\", \"tone\": \"teal\", \"title\": \"Special Education\"}, {\"icon\": \"fa-book-open\", \"text\": \"A balanced school day with classes, co-curricular activities and guided study time.\", \"tone\": \"orange\", \"title\": \"Full Day Session\"}, {\"icon\": \"fa-user-graduate\", \"text\": \"Experienced, trained and dedicated teachers who guide every student to succeed.\", \"tone\": \"teal\", \"title\": \"Qualified Teachers\"}]}, \"team\": {\"items\": [{\"name\": \"Mahmudul Hasan\", \"note\": null, \"photo\": null, \"designation\": \"Lecturer\"}, {\"name\": \"Nasrin Jahan\", \"note\": null, \"photo\": \"website/branch-1/people/U0bvmCSXE55AdwkiQGpmPUgozi0q10nipOHG1FWN.jpg\", \"designation\": \"Lecturer\"}]}, \"about\": {\"text\": null, \"title\": null, \"years\": null, \"points\": [], \"subtitle\": null, \"button_url\": null, \"image_main\": null, \"button_text\": null, \"years_label\": null, \"image_second\": null}, \"footer\": {\"text\": null, \"text_bn\": null}, \"social\": {\"youtube\": null, \"facebook\": null, \"linkedin\": null, \"instagram\": null}, \"messages\": {\"items\": [{\"name\": \"Principal 1\", \"note\": null, \"text\": \"BAF Shaheen College Dhaka is a reputed and profound educational institution run by Bangladesh Air Force. Since 1960, Shaheen has soared to new heights like an eagle with its guiding principles of education, restraint, and discipline, embodying the spirit of an eagle in its pursuit of excellence. Bangladesh is moving forward with irresistible progress. BAF Shaheen College Dhaka is dedicated to enhancing students\' knowledge and creativity through meticulous care and practice, guided by the Universal Education Policy. In addition to traditional teaching, the organization is also committed to encouraging the students to participate in life-oriented education, co-curricular activities and various club activities.\", \"photo\": \"website/branch-1/people/XGQH03kILflmhveM2jQMebgNjOG3Gt37wpWLTll3.jpg\", \"designation\": \"Principal / Head Teacher\"}, {\"name\": \"Jamal Uddin\", \"note\": null, \"text\": \"BAF Shaheen College Dhaka is a reputed and profound educational institution run by Bangladesh Air Force. Since 1960, Shaheen has soared to new heights like an eagle with its guiding principles of education, restraint, and discipline, embodying the spirit of an eagle in its pursuit of excellence. Bangladesh is moving forward with irresistible progress. BAF Shaheen College Dhaka is dedicated to enhancing students\' knowledge and creativity through meticulous care and practice, guided by the Universal Education Policy. In addition to traditional teaching, the organization is also committed to encouraging the students to participate in life-oriented education, co-curricular activities and various club activities.\", \"photo\": \"website/branch-1/people/JXFcHI6kslgnFim9tII1MBlucfXC4hSXiTIFyxQS.jpg\", \"designation\": \"Security Guard\"}]}, \"partners\": [], \"teachers\": {\"items\": []}}}', '2026-09-28 12:52:21', '2026-10-08 09:51:50', NULL),
