INSERT INTO `notices` (`id`, `institution_id`, `branch_id`, `group_uuid`, `title`, `body`, `category`, `audience`, `audience_filter`, `is_emergency`, `is_pinned`, `is_public`, `channels`, `status`, `publish_at`, `expires_at`, `published_at`, `published_by`, `distributed_at`, `attachment_path`, `attachment_name`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 1, 1, NULL, 'অর্ধবার্ষিক পরীক্ষার রুটিন প্রকাশ', 'আগামী মাসের প্রথম সপ্তাহ থেকে অর্ধবার্ষিক পরীক্ষা শুরু হবে। বিস্তারিত রুটিন শ্রেণি শিক্ষকের কাছ থেকে সংগ্রহ করো।\nপরীক্ষার আগে প্রবেশপত্র পোর্টাল থেকে ডাউনলোড করতে হবে।', 'exam', 'students', NULL, 0, 1, 0, '[]', 'published', '2026-09-30 05:40:55', NULL, '2026-09-30 05:40:55', 4, '2026-09-30 05:43:45', NULL, NULL, 4, '2026-09-30 05:40:55', '2026-09-30 05:43:45'),
(2, 1, 1, NULL, 'Guardians meeting on Saturday', 'All guardians are invited to the guardians\' meeting on Saturday at 10:00 in the school hall.\nWe will discuss the half-yearly results and the new co-curricular programme.', 'meeting', 'guardians', NULL, 0, 0, 0, '[]', 'published', '2026-09-30 05:43:45', NULL, '2026-09-30 05:43:45', 4, '2026-09-30 05:43:45', NULL, NULL, 4, '2026-09-30 05:43:45', '2026-09-30 05:43:45'),
(3, 1, 1, NULL, 'মহান স্বাধীনতা দিবস উপলক্ষে ছুটি', '২৬ মার্চ মহান স্বাধীনতা ও জাতীয় দিবস উপলক্ষে প্রতিষ্ঠান বন্ধ থাকবে। সকাল ৮টায় জাতীয় পতাকা উত্তোলন অনুষ্ঠানে সবাইকে উপস্থিত থাকার অনুরোধ করা হলো।', 'holiday', 'all', NULL, 0, 0, 0, '[]', 'published', '2026-09-30 05:43:45', '2026-10-20 05:43:45', '2026-09-30 05:43:45', 4, '2026-09-30 05:43:46', NULL, NULL, 4, '2026-09-30 05:43:45', '2026-09-30 05:43:46'),
